	<div class="post-content">
		<Content />
	</div>
</Layout>
=== src/pages/albums/index.astro
---
import { getCollection } from "astro:content";
import Layout from "../../layouts/Layout.astro";

const albums = await getCollection("albums");
albums.sort((a, b) => b.data.date.valueOf() - a.data.date.valueOf());

const byYear = new Map<number, typeof albums>();
for (const album of albums) {
	const year = album.data.date.getFullYear();
	byYear.set(year, [...(byYear.get(year) ?? []), album]);
}
const years = [...byYear.keys()].sort((a, b) => b - a);
---

<Layout title="Albums" description="Photo albums, organized by year.">
	<h1 class="mb-6">Albums</h1>
	{
		years.map((year) => (
			<section class="mb-6">
				<h2 class="mb-2">{year}</h2>
				<ul class="list-none space-y-1">
					{byYear.get(year)!.map((album) => (
						<li>
							<a
								href={`/albums/${album.id}/`}
								class="link"
							>
								{album.data.title}
							</a>
						</li>
					))}
				</ul>
			</section>
		))
	}
</Layout>
=== src/components/AlbumPost.astro
---
import { getResponsiveImageAttributes } from "@imagekit/javascript";
import { formatDate } from "../lib/garden";

interface Photo {
	path: string;
	alt: string;
	width: number;
	height: number;
}

interface Props {
	href: string;
	title: string;
	date: Date;
	photos: Photo[];
	priority?: boolean;
}

const { href, title, date, photos, priority } = Astro.props;

const urlEndpoint = import.meta.env.IMAGEKIT_URL_ENDPOINT;

// Like Instagram, every slide takes the first photo's proportions so the
// carousel doesn't jump in height while swiping; the rest are cropped to fit.
const [first] = photos;
const aspectRatio = `${first.width} / ${first.height}`;

const slides = photos.map((photo) => ({
	...photo,
	...getResponsiveImageAttributes({
		src: photo.path,
		urlEndpoint,
		sizes: "(min-width: 36rem) 36rem, 100vw",
		deviceBreakpoints: [640, 828, 1080, 1280],
		imageBreakpoints: [],
	}),
}));

// Phosphor (regular): caret-left, caret-right.
const icons = {
	prev: "M165.66,202.34a8,8,0,0,1-11.32,11.32l-80-80a8,8,0,0,1,0-11.32l80-80a8,8,0,0,1,11.32,11.32L91.31,128Z",
	next: "M181.66,133.66l-80,80a8,8,0,0,1-11.32-11.32L164.69,128,90.34,53.66a8,8,0,0,1,11.32-11.32l80,80A8,8,0,0,1,181.66,133.66Z",
};
---

<article class="mb-16">
	<p class="mb-3 text-sm text-muted dark:text-muted-dark">
		{title} · <span class="tabular-nums">{formatDate(date)}</span>
	</p>

	<div class="carousel group relative bleed">
		<ul
			class="carousel-track flex list-none snap-x snap-mandatory overflow-x-auto rounded-xl"
			style={{ aspectRatio }}
			aria-label={`${title}, ${photos.length} photos`}
		>
			{
				slides.map((slide, index) => (
					<li class="h-full w-full shrink-0 snap-start">
						<a href={href} class="block h-full" tabindex={index === 0 ? undefined : -1}>
							<img
								src={slide.src}
								srcset={slide.srcSet}
								sizes={slide.sizes}
								width={slide.width}
								height={slide.height}
								alt={slide.alt}
								loading={priority && index === 0 ? "eager" : "lazy"}
								fetchpriority={priority && index === 0 ? "high" : undefined}
								decoding="async"
								class="h-full w-full object-cover"
							/>
						</a>
					</li>
				))
			}
		</ul>

		{
			photos.length > 1 && (
				<>
					<button
						type="button"
						data-dir="-1"
						aria-label="Previous photo"
						class="carousel-button left-3"
					>
						<svg width="16" height="16" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">
							<path d={icons.prev} />
						</svg>
					</button>
					<button
						type="button"
						data-dir="1"
						aria-label="Next photo"
						class="carousel-button right-3"
					>
						<svg width="16" height="16" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">
							<path d={icons.next} />
						</svg>
					</button>
					<div class="carousel-dots" aria-hidden="true">
						{photos.map(() => <span />)}
					</div>
				</>
			)
		}
	</div>
</article>

<style>
	.carousel-dots {
		position: absolute;
		inset-inline: 0;
		bottom: 0.75rem;
		display: flex;
		justify-content: center;
		gap: 0.375rem;
		pointer-events: none;
	}

	.carousel-dots span {
		width: 0.375rem;
		height: 0.375rem;
		border-radius: 9999px;
		background: white;
		opacity: 0.5;
		box-shadow: 0 0 2px rgb(0 0 0 / 0.4);
		transition: opacity 0.15s ease;
	}

	.carousel-dots span[data-active] {
		opacity: 1;
	}

	.carousel-track {
		scrollbar-width: none;
	}

	.carousel-track::-webkit-scrollbar {
		display: none;
	}

	/* Arrows are for mouse users only; touch screens just swipe. */
	.carousel-button {
		display: none;
	}

	@media (hover: hover) {
		.carousel-button {
			position: absolute;
			top: 50%;
			translate: 0 -50%;
			display: grid;
			place-items: center;
			width: 2rem;
			height: 2rem;
			border-radius: 9999px;
			background: rgb(255 255 255 / 0.85);
			color: var(--color-ink);
			opacity: 0;
			transition: opacity 0.15s ease;
			cursor: pointer;
		}

		.carousel:hover .carousel-button:not(:disabled),
		.carousel-button:focus-visible {
			opacity: 1;
		}
	}
</style>

<script>
	for (const carousel of document.querySelectorAll<HTMLElement>(".carousel")) {
		const track = carousel.querySelector<HTMLElement>(".carousel-track")!;
		const dots = carousel.querySelectorAll<HTMLElement>(".carousel-dots span");
		const [prev, next] = carousel.querySelectorAll<HTMLButtonElement>(".carousel-button");
		if (!prev || !next) continue;

		const update = () => {
			const index = Math.round(track.scrollLeft / track.clientWidth);
			dots.forEach((dot, i) => dot.toggleAttribute("data-active", i === index));
			prev.disabled = index === 0;
			next.disabled = index === track.children.length - 1;
		};

		for (const button of [prev, next]) {
			button.addEventListener("click", () => {
				track.scrollBy({ left: Number(button.dataset.dir) * track.clientWidth, behavior: "smooth" });
			});
		}

		track.addEventListener("scroll", update, { passive: true });
		update();
	}
</script>
=== src/pages/photos.astro
---
import { getCollection, render } from "astro:content";
import Layout from "../layouts/Layout.astro";
import AlbumPost from "../components/AlbumPost.astro";
import { ogImageUrl } from "../lib/imagekit";

const albums = await getCollection("albums");
albums.sort((a, b) => b.data.date.valueOf() - a.data.date.valueOf());

const posts = (
	await Promise.all(
		albums.map(async (album) => {
			const { remarkPluginFrontmatter } = await render(album);
			const photos = (remarkPluginFrontmatter.photos ?? []) as Array<{
				path: string;
				alt: string;
				width: number;
				height: number;
			}>;
			return {
				href: `/albums/${album.id}/`,
				title: album.data.title,
				date: album.data.date,
				photos,
			};
		}),
	)
).filter((post) => post.photos.length > 0);

const ogImage = posts[0] ? ogImageUrl(posts[0].photos[0].path) : undefined;
---

<Layout
	title="Photos"
	description="A chronological stream of photos from my albums."
	image={ogImage}
>
	<h1 class="mb-6">Photos</h1>
	{posts.map((post, index) => <AlbumPost {...post} priority={index === 0} />)}
</Layout>
=== src/content/albums/copenhagen-2024.md
---
title: "Copenhagen"
date: 2024-11-17
---

A short trip to Copenhagen. We landed in the evening and the city was already lit up for winter.

![Copenhagen harbor at night](https://ik.imagekit.io/johnchque/website/photos/20241117_cph/cph_1.jpg?width=3499&height=2336 "The view from our hotel window")

The next morning we walked along the water, no real plan, just following whatever looked interesting.

![Copenhagen](https://ik.imagekit.io/johnchque/website/photos/20241117_cph/cph_2.jpg?width=3499&height=2336)

By the afternoon the light had turned soft and low, the kind that makes even ordinary streets look deliberate.

![Copenhagen](https://ik.imagekit.io/johnchque/website/photos/20241117_cph/cph_3.jpg?width=3499&height=2307 "Copenhagen, November 2024.")
=== src/content/reflections/to-write-again.md
---
title: "I want to write again"
createdAt: 2026-08-19
updatedAt: 2026-08-19
status: "seedling"
description: ""
---
I have been struggling to write down this piece for quite a while. I think I have been trying to define the perfect structure for my website so finally, when it is done, I can publish my thoughts. I think I was just delaying the process of writing again.

I feel that the last time I wrote something, I was focusing too much into making something useful for the world. I felt as if whatever I published, was going to be the next piece I was going to be proud of. However, a question kept crawling my mind: What is it worth?

Ever since I can recall, I have been in love with writing. Not necessarily essays, but also poems, thoughts, and other forms of expressing our minds. I adore to understand new languages and learn about all the possible ways they are connected. There is just so much, we as species, have develop in order to work together.

With AI taking over everything that means knowledge work, I have lost the spark I felt when I thought of writing. It felt as if every piece of text was just a regurgitated blob of statistically generated strings that somehow made sense. It felt as we started to devalue our own communication, and start optimising towards the machines. Of course, this is not only a tech issue. It is a social issue. It is linked to fascism, capitalism, patriarchy and multiple other fields of knowledge coming from social sciences.

All these thoughts prevented me from writing again. I was afraid that whatever instagram caption I would write would be used for training new AI models that would suggest me what to write on those captions themselves. As if every piece of text was not mine so why bother? But along the way, and along these months, I have realised that if there is a time in which we can make things with passion, it is now.

So this short piece is not a commitment to publish more often but rather to do it with more passion. To do it because it makes me human. Because I feel we are more and more neglecting the political nature of tech. And because when more and more companies want to make models to replace our creativity, I can always go back to my own.

I will write again.

