	.carousel-dots {
		position: absolute;
		inset-inline: 0;
		bottom: 0.75rem;
		display: flex;
		justify-content: center;
		gap: 0.375rem;
		pointer-events: none;
	}

	.carousel-dots span {
		width: 0.375rem;
		height: 0.375rem;
		border-radius: 9999px;
		background: white;
		opacity: 0.5;
		box-shadow: 0 0 2px rgb(0 0 0 / 0.4);
		transition: opacity 0.15s ease;
	}

	.carousel-dots span[data-active] {
		opacity: 1;
	}

	.carousel-track {
		scrollbar-width: none;
	}

	.carousel-track::-webkit-scrollbar {
		display: none;
	}

	/* Arrows are for mouse users only; touch screens just swipe. */
	.carousel-button {
		display: none;
	}

