import { getCollection, render } from "astro:content";
import { formatDate, formatMonth } from "./garden";

export interface Photo {
	path: string;
	alt: string;
	caption?: string;
	width: number;
	height: number;
}

export interface FeedPost {
	id: string;
	href: string;
	title?: string;
	date: Date;
	monthOnly: boolean;
	photos: Photo[];
	excerpt: string;
	truncated: boolean;
}

export function formatPostDate(date: Date, monthOnly: boolean): string {
	return monthOnly ? formatMonth(date) : formatDate(date);
}

// Month-only posts sort as if written at the very end of their month, so they
// sit at the top of that month's posts.
function sortKey(post: FeedPost): number {
	if (!post.monthOnly) return post.date.valueOf();
	const { date } = post;
	return new Date(date.getFullYear(), date.getMonth() + 1, 1).valueOf() - 1;
}

// Long enough for a tweet-sized post to show in full; anything longer is a
// reflection and gets cut off with a link to its own page.
const EXCERPT_LENGTH = 280;

function toPlainText(markdown: string): string {
	return markdown
		.replace(/!\[[^\]]*\]\([^)]*\)/g, "")
		.replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
		.replace(/^#+\s+/gm, "")
		.replace(/[*_`>]/g, "")
		.replace(/\s+/g, " ")
		.trim();
}

function excerpt(markdown: string): { excerpt: string; truncated: boolean } {
	const text = toPlainText(markdown);
	if (text.length <= EXCERPT_LENGTH) return { excerpt: text, truncated: false };
	const cut = text.slice(0, EXCERPT_LENGTH);
	return {
		excerpt: `${cut.slice(0, cut.lastIndexOf(" ")).replace(/[,.;:!?]$/, "")}…`,
		truncated: true,
	};
}

export async function getFeedPosts(): Promise<FeedPost[]> {
	const entries = await getCollection("feed");

	const posts = await Promise.all(
		entries.map(async (entry) => {
			const { remarkPluginFrontmatter } = await render(entry);
			return {
				id: entry.id,
				href: `/feed/${entry.id}/`,
				title: entry.data.title,
				date: entry.data.date,
				monthOnly: entry.data.monthOnly,
				photos: (remarkPluginFrontmatter.photos ?? []) as Photo[],
				...excerpt(entry.body ?? ""),
			};
		}),
	);

	posts.sort((a, b) => sortKey(b) - sortKey(a));
	return posts;
}

