---
import Carousel from "./Carousel.astro";
import { formatPostDate, type FeedPost } from "../lib/feed";

interface Props {
	post: FeedPost;
	priority?: boolean;
}

const { post, priority } = Astro.props;
const { href, title, date, monthOnly, photos, excerpt } = post;
const displayDate = formatPostDate(date, monthOnly);
---

{
	photos.length > 0 ? (
		<article class="mb-16">
			<p class="mb-2 text-sm text-muted dark:text-muted-dark">
				<a href={href} class="tabular-nums hover:text-evening dark:hover:text-sunset">
					{displayDate}
				</a>
			</p>
			{title && (
				<h2 class="mb-3">
					<a href={href} class="hover:text-evening dark:hover:text-sunset">
						{title}
					</a>
				</h2>
			)}
			<Carousel
				href={href}
				label={title ?? `Post from ${displayDate}`}
				photos={photos}
				priority={priority}
			/>
		</article>
	) : (
		// Text posts are one big link: the carousel above has its own links and
		// buttons, so only these can be wrapped whole.
		<article class="mb-16">
			<a href={href} class="group block">
				<p class="mb-2 text-sm text-muted tabular-nums dark:text-muted-dark">
					{displayDate}
				</p>
				{title && (
					<h2 class="mb-3 group-hover:text-evening dark:group-hover:text-sunset">
						{title}
					</h2>
				)}
				<p class="line-clamp-3 text-muted dark:text-muted-dark">{excerpt}</p>
			</a>
		</article>
	)
}
EOF
