---
import Layout from "../../layouts/Layout.astro";
import ProjectCard from "../../components/ProjectCard.astro";
import { getProjects, type Project } from "../../lib/workbench";

const projects = await getProjects();

const byYear = new Map<number, Project[]>();
for (const project of projects) {
	const year = project.data.date.getFullYear();
	byYear.set(year, [...(byYear.get(year) ?? []), project]);
}
const years = [...byYear.keys()].sort((a, b) => b - a);
---

<Layout
	title="Workbench"
	description="A consolidated list of all the things I created along the years."
>
	<h1 class="mb-2">Workbench</h1>
	<section class="post-content mb-10">
		<p>A consolidated list of all the things I created along the years.</p>
		<p>
			The projects listed here have multiple shapes and forms, with
			different collaborators and purposes. They go from making a music
			video for a friend to having my own startup.
		</p>
		<p>
			I love building and creating things. That's why the list you see
			here is diverse in nature. I always love to explore new knowledge
			areas and even better if they are outside my common expertise.
		</p>
	</section>
	{
		years.map((year) => (
			<section class="mb-8">
				<h2 class="font-sans text-sm tabular-nums">{year}</h2>
				<ul class="list-none">
					{byYear.get(year)!.map((project) => (
						<ProjectCard project={project} />
					))}
				</ul>
			</section>
		))
	}
</Layout>

<li class="border-b border-black/10 last:border-b-0 dark:border-white/10">
	<Card
		href={linked ? `/workbench/${project.id}/` : undefined}
		class:list={["block py-4", linked && "group"]}
	>
		<span class:list={[linked ? "link" : "text-ink dark:text-white"]}
			>{title}</span
		>
		<p class="text-muted dark:text-muted-dark">{description}</p>
		<p class="mt-1 text-xs text-muted dark:text-muted-dark">
			{formatType(type)} · {role}
		</p>
	</Card>
</li>

