content.content:
---
import Carousel from "./Carousel.astro";
import { formatPostDate, type FeedPost } from "../lib/feed";

interface Props {
	post: FeedPost;
	priority?: boolean;
}

const { post, priority } = Astro.props;
const { href, title, date, monthOnly, photos, excerpt } = post;
const displayDate = formatPostDate(date, monthOnly);
---

{
	photos.length > 0 ? (
		<article class="mb-16">
			<p class="mb-2 text-sm text-muted dark:text-muted-dark">
				<a href={href} class="tabular-nums hover:text-evening dark:hover:text-sunset">
					{displayDate}
				</a>
			</p>
			{title && (
				<h2 class="mb-3">
					<a href={href} class="hover:text-evening dark:hover:text-sunset">
						{title}
					</a>
				</h2>
			)}
			<Carousel
