---
import { formatType, hasPage, type Project } from "../lib/workbench";

interface Props {
	project: Project;
}

const { project } = Astro.props;
const { title, type, role, description, date, url } = project.data;

// Projects with a write-up are one big link to their page; projects that only
// live elsewhere link out; the rest are plain cards.
const href = hasPage(project) ? `/workbench/${project.id}/` : url;
const external = !hasPage(project) && Boolean(url);
const Card = href ? "a" : "div";
---

<li>
	<Card
		href={href}
		target={external ? "_blank" : undefined}
		rel={external ? "noopener noreferrer" : undefined}
		data-external-icon={external ? "" : undefined}
		class:list={["block py-5", href && "group"]}
	>
		<span
			class:list={[href ? "link" : "text-ink dark:text-white", external && "external-icon"]}
			>{title}</span
		>
		<p class="text-sm text-muted dark:text-muted-dark">{description}</p>
		<p class="mt-1 text-xs text-muted dark:text-muted-dark">
			<span class="tabular-nums">{date.getFullYear()}</span> ·{" "}
			{formatType(type)} · {role}
		</p>
	</Card>
</li>

---
interface Props {
	href: string;
	title: string;
}

const { href, title } = Astro.props;
---

<!--
	A minimal bordered card. The whole card is clickable through the title
	link's ::after overlay rather than an outer <a>, so the description can
	still hold links of its own (an <a> can't contain another <a>).
-->
<div
	class="card group relative rounded-xl bg-black/4 p-4 transition-colors duration-150 hover:bg-black/6 dark:bg-white/5 dark:hover:bg-white/8"
>
	<a href={href} class="link after:absolute after:inset-0 after:content-['']">
		{title}
	</a>
	<div class="text-muted dark:text-muted-dark">
		<slot />
	</div>
</div>

<style>
	/* Links inside the description sit above the card-wide overlay. */
	.card :global(div a) {
		position: relative;
		z-index: 1;
	}
</style>

---
import { render } from "astro:content";
import Layout from "../../layouts/Layout.astro";
import { formatType, getProjects, hasPage } from "../../lib/workbench";
import { ogImageUrl } from "../../lib/imagekit";

export async function getStaticPaths() {
	const projects = await getProjects();
	return projects.filter(hasPage).map((project) => ({
		params: { slug: project.id },
		props: { project },
	}));
}

const { project } = Astro.props;
const { Content, remarkPluginFrontmatter } = await render(project);

const firstPhoto = remarkPluginFrontmatter.photos?.[0];
const ogImage = firstPhoto ? ogImageUrl(firstPhoto.path) : undefined;

const { title, description, type, role, date } = project.data;
const facts = [
	["Type", formatType(type)],
	["Role", role],
	["Year", String(date.getFullYear())],
];
---

<Layout title={title} description={description} image={ogImage}>
	<a
		href="/workbench/"
		class="mb-6 inline-block text-sm text-muted hover:text-evening dark:text-muted-dark dark:hover:text-sunset"
	>
		← Workbench
	</a>
	<h1 class="mb-3">{title}</h1>
	<p class="mb-8 text-muted dark:text-muted-dark">{description}</p>
	<dl
		class="mb-16 grid grid-cols-2 gap-x-6 gap-y-4 border-y border-black/10 py-4 sm:grid-flow-col sm:grid-cols-none dark:border-white/10"
	>
		{
			facts.map(([label, value]) => (
				<div>
					<dt class="mb-1 text-xs text-muted dark:text-muted-dark">{label}</dt>
					<dd class="text-sm">{value}</dd>
				</div>
			))
		}
	</dl>
	<div class="post-content">
		<Content />
	</div>
</Layout>

