import { getCollection, render } from "astro:content";
import { formatDate, formatMonth } from "./garden";

export interface Photo {
	path: string;
	alt: string;
	caption?: string;
	width: number;
	height: number;
}

export interface FeedPost {
	id: string;
	href: string;
	title?: string;
	date: Date;
	monthOnly: boolean;
	photos: Photo[];
	excerpt: string;
	readingMinutes: number;
}

export function formatPostDate(date: Date, monthOnly: boolean): string {
	return monthOnly ? formatMonth(date) : formatDate(date);
}

// Month-only posts sort as if written at the very end of their month, so they
// sit at the top of that month's posts.
function sortKey(post: FeedPost): number {
	if (!post.monthOnly) return post.date.valueOf();
	const { date } = post;
	return new Date(date.getFullYear(), date.getMonth() + 1, 1).valueOf() - 1;
}

// The feed clamps text to three lines in CSS; this only keeps long
// reflections from shipping their whole body into the feed's HTML.
const EXCERPT_LENGTH = 400;

function excerpt(markdown: string): string {
	return markdown
		.replace(/!\[[^\]]*\]\([^)]*\)/g, "")
		.replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
		.replace(/^#+\s+/gm, "")
		.replace(/[*_`>]/g, "")
		.replace(/\s+/g, " ")
		.trim()
		.slice(0, EXCERPT_LENGTH);
}

// At a relaxed ~200 words a minute, never less than one.
function readingMinutes(markdown: string): number {
	const words = markdown.split(/\s+/).filter(Boolean).length;
	return Math.max(1, Math.round(words / 200));
}

export async function getFeedPosts(): Promise<FeedPost[]> {
	const entries = await getCollection("feed");

	const posts = await Promise.all(
		entries.map(async (entry) => {
			const { remarkPluginFrontmatter } = await render(entry);
			return {
				id: entry.id,
				href: `/feed/${entry.id}/`,
				title: entry.data.title,
				date: entry.data.date,
				monthOnly: entry.data.monthOnly,
				photos: (remarkPluginFrontmatter.photos ?? []) as Photo[],
				excerpt: excerpt(entry.body ?? ""),
				readingMinutes: readingMinutes(entry.body ?? ""),
			};
		}),
	);

	posts.sort((a, b) => sortKey(b) - sortKey(a));
	return posts;
}
import { defineCollection } from "astro:content";
import { glob } from "astro/loaders";
import { z } from "astro/zod";

// One stream for everything short-lived: text posts, reflections and photo
// albums. Photos are read from the Markdown body by rehype-photos, so a post
// with photos is an album and one without is text.
//
// `date` is either a full day (2024-11-17) or just a month (2024-11) for
// posts that shouldn't be pinned to an exact day. YAML reads the month form
// as a plain string, which is how the two are told apart.
const feed = defineCollection({
	loader: glob({ pattern: "**/*.md", base: "./src/content/feed" }),
	schema: z
		.object({
			title: z.string().optional(),
			date: z.union([z.string().regex(/^\d{4}-\d{2}$/), z.coerce.date()]),
		})
		.transform(({ date, ...rest }) => {
			if (typeof date !== "string") return { ...rest, date, monthOnly: false };
			const [year, month] = date.split("-").map(Number);
			return { ...rest, date: new Date(year, month - 1, 1), monthOnly: true };
		}),
});

const gardenSchema = z.object({
	title: z.string(),
	createdAt: z.coerce.date(),
	updatedAt: z.coerce.date(),
	status: z.enum(["seedling", "budding", "evergreen"]).default("seedling"),
	description: z.string().optional(),
});

const essays = defineCollection({
	loader: glob({ pattern: "**/*.md", base: "./src/content/essays" }),
	schema: gardenSchema,
});

const notes = defineCollection({
	loader: glob({ pattern: "**/*.md", base: "./src/content/notes" }),
	schema: gardenSchema,
});

// Projects of every kind (startups, organizations, videos, books, comics).
// A project with a Markdown body gets its own page; one without is just a
// line on /workbench.
const workbench = defineCollection({
	loader: glob({ pattern: "**/*.md", base: "./src/content/workbench" }),
	schema: z.object({
		title: z.string(),
		date: z.coerce.date(),
		description: z.string(),
		// Singular and lowercase ("music video", "startup").
		type: z.string().transform((type) => type.toLowerCase()),
		role: z.string(),
		with: z.string().optional(),
		// Where a project without its own page lives elsewhere (a site, a
		// social profile); its card links out there instead.
		url: z.url().optional(),
	}),
---
import { getCollection, render } from "astro:content";
import Layout from "../../layouts/Layout.astro";
import { formatPostDate } from "../../lib/feed";
import { ogImageUrl } from "../../lib/imagekit";

export async function getStaticPaths() {
	const posts = await getCollection("feed");
	return posts.map((post) => ({
		params: { slug: post.id },
		props: { post },
	}));
}

const { post } = Astro.props;
const { Content, remarkPluginFrontmatter } = await render(post);

const firstPhoto = remarkPluginFrontmatter.photos?.[0];
const ogImage = firstPhoto ? ogImageUrl(firstPhoto.path) : undefined;
const date = formatPostDate(post.data.date, post.data.monthOnly);
---

<Layout
	title={post.data.title ?? `Post from ${date}`}
	description={post.data.title
		? `${post.data.title}, from my feed.`
		: `A post from my feed, ${date}.`}
	image={ogImage}
>
