---
import Carousel from "./Carousel.astro";
import { formatPostDate, type FeedPost } from "../lib/feed";

interface Props {
	post: FeedPost;
	priority?: boolean;
}

const { post, priority } = Astro.props;
const { href, title, note, date, monthOnly, photos, excerpt, readingMinutes, Content } =
	post;
const displayDate = formatPostDate(date, monthOnly);

const kind = photos.length > 0 ? "album" : title ? "long" : "short";
const metaClass = "mb-1 text-xs tabular-nums text-muted dark:text-muted-dark";
---

{
	kind === "album" && (
		<article class="py-6">
			<p class={metaClass}>
				{displayDate}
				{note && <span class="note">{note}</span>}
			</p>
			{title && (
				<h2 class="mb-3 text-lg">
					<a href={href} class="link">
						{title}
					</a>
				</h2>
			)}
			<Carousel
				href={href}
				label={title ?? `Post from ${displayDate}`}
				photos={photos}
				priority={priority}
			/>
		</article>
	)
}
{
	// Long text posts are one big link: the carousel above has its own links
	// and buttons, so only these can be wrapped whole.
	kind === "long" && (
		<article class="py-6">
			<a href={href} class="group block">
				<p class={metaClass}>
					{displayDate} · {readingMinutes} min read
					{note && <span class="note">{note}</span>}
				</p>
				<h2 class="text-lg">
					<span class="link">{title}</span>
				</h2>
				<p class="text-sm line-clamp-4 text-muted dark:text-muted-dark">
					{excerpt}
				</p>
			</a>
		</article>
	)
}
{
	// Short posts are shown whole, like a tweet; the date is the permalink.
	kind === "short" && (
		<article class="py-6">
			<p class={metaClass}>
				<a href={href} class="hover:text-evening dark:hover:text-sunset">
					{displayDate}
				</a>
				{note && <span class="note">{note}</span>}
			</p>
			<div class="post-content">
				<Content />
			</div>
		</article>
	)
}

<style>
	/* Handwritten aside next to the date, in the same hand as the site name. */
	.note {
		margin-inline-start: 0.5rem;
		font-family: var(--font-handwriting);
		font-size: 1.125rem;
		line-height: 1;
		color: var(--color-evening);
	}

	:global(html.dark) .note {
		color: var(--color-sunset);
	}
</style>

